  textMuted: "#bfc1c5",
  textSubtle: "#8c93a8",
  orange: "#F86606",
  orangeDeep: "#FF4800",
  orangeTint: "rgba(248,102,6,0.16)",
};

const FONT_MARKETING = "'GT Walsheim', Inter, sans-serif";
const FONT_PRIMARY = "Inter, sans-serif";
const FONT_MONO = "'JetBrains Mono', monospace";

export const fps = 25;

// Canvas is 3840x2160. Fit chrome inside with margin.
const CHROME_W = 3200;
const CHROME_H = 1700;

const SPRINGS = {
  SNAPPY: { damping: 18, mass: 0.7, stiffness: 160 },
  ELASTIC: { damping: 10, mass: 0.6, stiffness: 140 },
  LIQUID: { damping: 22, mass: 1.0, stiffness: 110 },
  GENTLE: { damping: 28, mass: 1.2, stiffness: 90 },
  OVERDAMPED: { damping: 40, mass: 1, stiffness: 200 },
};

const springIn = (
  frame: number,
  fps: number,
  delay: number,
  preset: keyof typeof SPRINGS
) => spring({ frame, fps, delay, config: SPRINGS[preset] });

const ambientDrift = (
  frame: number,
  amplitude: number,
  period: number,
  seed: string
) => {
  let h = 0;
  for (let i = 0; i < seed.length; i++) h = (h * 31 + seed.charCodeAt(i)) | 0;
  const phase = (h % 1000) / 1000;
  const t = frame / period + phase * Math.PI * 2;
  return Math.sin(t) * amplitude + Math.sin(t * 1.7) * amplitude * 0.3;
};

const sceneExit = (frame: number, dur: number) => {
  if (!isFinite(dur)) return { opacity: 1, transform: "translateY(0px) scale(1)" };
  const tail = 14;
  const start = dur - tail;
  if (frame < start) return { opacity: 1, transform: "translateY(0px) scale(1)" };
  const p = Math.min(1, (frame - start) / tail);
  return {
    opacity: 1 - p,
    transform: `translateY(${-p * 10}px) scale(${1 - p * 0.02})`,
  };
};

